import{_ as a,o as t,c as s,a2 as i}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"RFC 0081 — Per-plugin installable PWA","description":"","frontmatter":{"sourceUrl":"https://github.com/sovereignfs/sovereign/blob/main/docs/rfcs/0081-per-plugin-installable-pwa.md"},"headers":[],"relativePath":"rfcs/0081-per-plugin-installable-pwa.md","filePath":"rfcs/0081-per-plugin-installable-pwa.md"}'),n={name:"rfcs/0081-per-plugin-installable-pwa.md"};function o(l,e,r,d,c,p){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="rfc-0081-—-per-plugin-installable-pwa" tabindex="-1">RFC 0081 — Per-plugin installable PWA <a class="header-anchor" href="#rfc-0081-—-per-plugin-installable-pwa" aria-label="Permalink to &quot;RFC 0081 — Per-plugin installable PWA&quot;">​</a></h1><p><strong>Status:</strong> Partially implemented (epic task 2.25 shipped at v0.84.0; task 2.26, icon generation, still open)<br><strong>Date:</strong> July 2026<br><strong>Author:</strong> kasunben<br><strong>Scope:</strong> <code>runtime/app/api/manifest/</code> (new <code>[pluginId]</code> dynamic segment extending the existing dynamic-manifest route), <code>runtime/app/(platform)/layout.tsx</code> (per-plugin <code>generateMetadata</code>), <code>runtime/middleware.ts</code> (per-plugin login rewrite), <code>packages/manifest</code> (new optional <code>installable</code> field), <code>scripts/</code> (plugin PWA icon generation), <code>docs/plugin-development.md</code>, <code>docs/architecture-rules.md</code>. Builds on RFC 0013 (mobile responsiveness &amp; PWA), RFC 0027 Phase 3 (dynamic PWA manifest — epic task 9.10), RFC 0074/0078 (offline-capable plugins), RFC 0075 (mobile chrome toggle). Prerequisite-adjacent to RFC 0082 (focused plugin app shell); ships independently of it. Builds on research <a href="./../research/0006-standalone-plugin-apps.html">0006</a>.<br><strong>Incorporated into plan:</strong> Yes — epic tasks 2.25–2.26.</p><hr><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>Let an individual plugin be installed as its <strong>own</strong> home-screen app. A plugin opting in with <code>installable: true</code> gets a dedicated web app manifest served from <code>/api/manifest/&lt;pluginId&gt;</code>, scoped to its <code>routePrefix</code>, carrying its own name and icons. The user installs &quot;Tally&quot; from their browser and gets a chrome-less, offline-capable app with its own springboard icon — no app store, no native shell, no new repository.</p><p>This is the cheapest rung of the standalone-plugin-app ladder in research 0005, and it is deliberately shipped first: if a focused, offline, home-screen plugin app does not feel like an app, no amount of Capacitor work fixes that. It is also fully additive and reversible.</p><h2 id="motivation" tabindex="-1">Motivation <a class="header-anchor" href="#motivation" aria-label="Permalink to &quot;Motivation&quot;">​</a></h2><p>Sovereign already installs as a PWA, but only as <em>Sovereign</em> — one manifest, one icon, <code>scope: &quot;/&quot;</code>, <code>start_url: &quot;/&quot;</code>. A user who mainly uses one app on their instance still installs the whole workspace and navigates into it every time.</p><p>Meanwhile the platform has quietly acquired every ingredient a per-plugin app needs: offline document caching for a declared plugin route (RFC 0074/0078), client-hydrated data via <code>sdk.offline</code>, chrome-less layout via <code>shell: &quot;minimal&quot;</code> or <code>shellConfig.mobileHeader/mobileFooter</code> (RFC 0075), and a dynamic white-labeled manifest route. What is missing is the small amount of plumbing that points a manifest at one plugin instead of the whole instance.</p><h2 id="current-state-what-this-builds-on" tabindex="-1">Current state (what this builds on) <a class="header-anchor" href="#current-state-what-this-builds-on" aria-label="Permalink to &quot;Current state (what this builds on)&quot;">​</a></h2><ul><li><p><strong>A dynamic PWA manifest route already exists</strong> — <code>runtime/app/api/manifest/route.ts</code> serves the manifest with the tenant&#39;s brand name from <code>getInstanceConfig()</code>, falling back gracefully on DB failure. Its own doc comment notes it is &quot;the authoritative one for browsers&quot; while <code>runtime/public/manifest.json</code> is kept for <code>@ducanh2912/next-pwa</code> build-time tooling. <code>runtime/app/layout.tsx:29</code> points Next metadata at it (<code>manifest: &#39;/api/manifest&#39;</code>).</p><blockquote><p><strong>Roadmap accuracy note:</strong> epic task 9.10 (&quot;White-labeling, Phase 3 — Dynamic PWA manifest + favicon route&quot;, <code>docs/epics/design-system.md:353</code>) is still marked 📋 even though the dynamic manifest half of it is clearly implemented. Worth reconciling separately; this RFC assumes the route as it exists today.</p></blockquote></li><li><p><strong><code>manifest</code> is already a reserved, session-exempt API segment.</strong> It is in <code>RESERVED_API_SEGMENTS</code> (<code>runtime/src/api-namespace.ts</code>) and explicitly excluded from the middleware matcher (<code>runtime/middleware.ts:519</code>) with the comment &quot;browsers fetch it before login for PWA install&quot;. <strong>This is why per-plugin manifests belong under <code>/api/manifest/</code> and not at <code>/&lt;routePrefix&gt;/manifest.webmanifest</code></strong> — the latter sits inside the session-gated namespace, so a logged-out visitor would be redirected to <code>/login</code> instead of receiving a manifest, and no install prompt would ever appear.</p></li><li><p><strong>Build-time image generation is established.</strong><code>runtime/app/layout.tsx:35</code> references <code>scripts/generate-splash.ts</code>, which generates iOS startup images to avoid &quot;a blank white flash on standalone launch&quot;. Plugin icon rasterization follows the same pattern rather than inventing one.</p></li><li><p><strong>Offline is already per-plugin.</strong> <code>runtime/src/registry.ts:37</code> resolves <code>offline === true</code> into the plugin&#39;s bare <code>routePrefix</code>; the <code>offline-shells</code> Workbox cache serves that document; <code>runtime/middleware.ts:474</code> flags it; <code>runtime/app/(platform)/layout.tsx:50</code> renders the user-neutral shell and re-hydrates personalized chrome client-side.</p></li><li><p><strong>Plugin icons are a single SVG.</strong> Manifests declare <code>icon</code> (e.g. <code>sovereign-tally.local/manifest.json</code> → <code>icon.svg</code>). PWA install requires raster PNGs at 192 and 512 plus a maskable variant, so a plugin&#39;s current icon field is insufficient on its own.</p></li><li><p><strong>The login gate redirects out of scope.</strong> An unauthenticated request 303s to <code>/login</code> (<code>runtime/middleware.ts:328</code>). <code>runtime/middleware.ts:320</code> already handles the analogous problem for <code>/</code>, and its comment explains why: iOS resolves an installed app&#39;s launch/splash image from the <em>direct</em> response to <code>start_url</code> and does not follow a redirect, so a cold launch with no session shows a blank white screen. It <strong>rewrites</strong> instead.</p></li><li><p><strong>There is exactly one service worker</strong>, registered at <code>/</code> by <code>@ducanh2912/next-pwa</code>.</p></li></ul><h2 id="proposed-design" tabindex="-1">Proposed design <a class="header-anchor" href="#proposed-design" aria-label="Permalink to &quot;Proposed design&quot;">​</a></h2><h3 id="_1-manifest-opt-in-installable" tabindex="-1">1. Manifest opt-in: <code>installable</code> <a class="header-anchor" href="#_1-manifest-opt-in-installable" aria-label="Permalink to &quot;1. Manifest opt-in: \`installable\`&quot;">​</a></h3><div class="language-jsonc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">jsonc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;installable&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>A new optional boolean in <code>packages/manifest/src/schema.ts</code>. Absent/<code>false</code> means today&#39;s behavior — the plugin is reachable inside the Sovereign PWA and has no manifest of its own. Purely additive; <code>@sovereignfs/manifest</code> takes a <strong>minor</strong> bump.</p><p><strong>Deliberately separate from <code>offline</code>.</strong> They answer different questions: a plugin can be installable without offline support (it just needs a network), and offline-capable without being separately installable (Launcher, today). Deriving one from the other would couple two independent product decisions. The docs should recommend pairing them, because an installed app that fails on a cold launch with no signal is a poor app — but that is guidance, not a schema constraint.</p><p><code>installable: true</code> additionally requires a raster icon set (§3), enforced at manifest-validation time so the failure is a build error rather than a broken install prompt.</p><h3 id="_2-per-plugin-manifest-route" tabindex="-1">2. Per-plugin manifest route <a class="header-anchor" href="#_2-per-plugin-manifest-route" aria-label="Permalink to &quot;2. Per-plugin manifest route&quot;">​</a></h3><p>Extend the existing route into <code>runtime/app/api/manifest/[pluginId]/route.ts</code>, reusing its instance-config lookup and graceful-degradation behavior:</p><div class="language-jsonc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">jsonc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Tally&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;short_name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Tally&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;description&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Shared expense tracking and debt settlement.&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;start_url&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/tally&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;scope&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/tally&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/tally&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;display&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;standalone&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;display_override&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;standalone&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;minimal-ui&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;icons&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/* from the plugin&#39;s generated raster set */</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;theme_color&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;…&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;background_color&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;…&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><ul><li><code>name</code>/<code>description</code> come from the plugin manifest; the instance name is <strong>not</strong> prepended — the user is installing Tally, not &quot;MyInstance Tally&quot;.</li><li><code>start_url</code>, <code>scope</code>, and <code>id</code> are all the plugin&#39;s <code>routePrefix</code>. An explicit <code>id</code> keeps the installed identity stable if <code>start_url</code> ever gains a query parameter.</li><li><code>theme_color</code>/<code>background_color</code> inherit the instance&#39;s values, so a white-labeled instance&#39;s apps match it.</li><li>Unknown plugin id, plugin not installed, plugin disabled, or <code>installable !== true</code> → <strong>404</strong>. A manifest for a plugin the user cannot use would offer an install that leads nowhere.</li></ul><p>The route stays session-exempt by living under the already-excluded <code>manifest</code> segment. It leaks only what the plugin manifest already publishes (name, description, icon) — no per-user data, so the exemption is safe. This must be stated in the route&#39;s doc comment, since &quot;session-exempt&quot; deserves a written justification wherever it appears.</p><h3 id="_3-icon-generation" tabindex="-1">3. Icon generation <a class="header-anchor" href="#_3-icon-generation" aria-label="Permalink to &quot;3. Icon generation&quot;">​</a></h3><p><code>installable: true</code> requires PNG icons at 192×192 and 512×512 plus a maskable 512×512. Two supported paths:</p><ol><li><strong>Generated</strong> (default) — a build step rasterizes the plugin&#39;s existing <code>icon.svg</code> into the required set, following <code>scripts/generate-splash.ts</code>&#39;s pattern. Output is gitignored generated content, like <code>runtime/generated/</code>.</li><li><strong>Author-supplied</strong> — a plugin may ship its own raster set and declare it, for cases where a naive rasterization of a monochrome glyph makes a poor springboard icon (which is most of them, honestly — a maskable icon needs safe-area padding and usually a background plate that an SVG glyph does not have).</li></ol><p>The implementation task must decide whether generated icons get an automatic background plate for the maskable variant. Recommended: yes, using the instance&#39;s <code>background_color</code>, since a transparent maskable icon renders as a floating glyph on a platform-chosen background and looks broken on Android.</p><h3 id="_4-pointing-the-document-at-the-right-manifest" tabindex="-1">4. Pointing the document at the right manifest <a class="header-anchor" href="#_4-pointing-the-document-at-the-right-manifest" aria-label="Permalink to &quot;4. Pointing the document at the right manifest&quot;">​</a></h3><p><code>runtime/app/layout.tsx:29</code> sets <code>manifest: &#39;/api/manifest&#39;</code> globally. Add a <code>generateMetadata</code> to <code>runtime/app/(platform)/layout.tsx</code> that reads the already-injected <code>x-sovereign-plugin-id</code> header, looks the plugin up in the registry, and overrides <code>manifest</code> with <code>/api/manifest/&lt;pluginId&gt;</code> when that plugin is <code>installable</code>. Next composes nested metadata, so the plugin value wins for plugin routes and the instance manifest remains the default everywhere else.</p><p><strong>iOS needs more than the manifest.</strong> Apple resolves the home-screen icon from <code>apple-touch-icon</code> link tags and the launch image from <code>apple-touch-startup-image</code> — document head tags, not manifest entries (which is why <code>scripts/generate-splash.ts</code> exists at all). Per-plugin installs therefore need per-plugin values for these tags in the same <code>generateMetadata</code>, or an installed plugin app will wear the Sovereign icon and flash white on launch. This is the single easiest part of this RFC to overlook and the most visible when missed.</p><h3 id="_5-login-containment-—-the-concrete-bug-this-must-not-ship-with" tabindex="-1">5. Login containment — the concrete bug this must not ship with <a class="header-anchor" href="#_5-login-containment-—-the-concrete-bug-this-must-not-ship-with" aria-label="Permalink to &quot;5. Login containment — the concrete bug this must not ship with&quot;">​</a></h3><p>With <code>scope: &quot;/tally&quot;</code>, an installed app that navigates to <code>/login</code> leaves scope. Depending on platform that either opens a browser tab or shows an out-of-scope banner — in both cases login inside the installed app is broken, and on iOS a cold launch with no session shows a blank white screen for the reasons <code>runtime/middleware.ts:320</code> already documents for <code>/</code>.</p><p><strong>Resolution:</strong> generalize the existing <code>/</code> special case. When an unauthenticated GET targets an <code>installable</code> plugin&#39;s bare <code>routePrefix</code>, <strong>rewrite</strong> to the login document instead of redirecting, so the response is a real 200 with a full <code>&lt;head&gt;</code> at the in-scope URL. The existing rule that this must be a rewrite and not a 303 applies unchanged, as does the rule that any redirect to login must target <code>SOVEREIGN_AUTH_PUBLIC_URL</code> rather than the internal URL.</p><p>Post-login navigation must return to the plugin&#39;s route, not <code>/</code>, or the installed app lands outside its own scope immediately after sign-in.</p><h3 id="_6-service-worker-—-explicitly-unchanged" tabindex="-1">6. Service worker — explicitly unchanged <a class="header-anchor" href="#_6-service-worker-—-explicitly-unchanged" aria-label="Permalink to &quot;6. Service worker — explicitly unchanged&quot;">​</a></h3><p><strong>No second service worker, and no scope change to the existing one.</strong> Manifest <code>scope</code> governs the <em>installed app&#39;s navigation containment</em>; service-worker registration is independent and per-path. The root SW continues to serve <code>/tally/*</code>, so an installed plugin app inherits the existing offline behavior with no new registration, no overlapping caches, and no new opportunity to replay a cached document to the wrong user.</p><p>The hard rule that <code>pages</code>/<code>pages-rsc</code>/<code>pages-rsc-prefetch</code> stay <code>NetworkFirst</code> (never stale-serving, because pages are per-user SSR) therefore applies unchanged. This RFC introduces no surface-varying SSR, so RFC 0080 §5&#39;s cache-keying question does not arise here.</p><h3 id="docker-config-impact" tabindex="-1">Docker / config impact <a class="header-anchor" href="#docker-config-impact" aria-label="Permalink to &quot;Docker / config impact&quot;">​</a></h3><p>One new generated-asset directory for plugin PWA icons, which must be included in the runtime image and served as static assets. If icon generation runs at build time, it joins the <code>generate</code> step; the <code>.dockerignore</code> and any served-asset path list need checking. Flagged per the repo&#39;s Docker-impact rule; no new env var, port, or native dependency.</p><h2 id="ui-flows" tabindex="-1">UI flows <a class="header-anchor" href="#ui-flows" aria-label="Permalink to &quot;UI flows&quot;">​</a></h2><p><strong>Install:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>browser → user opens /tally → document links /api/manifest/fs.sovereign.tally</span></span>
<span class="line"><span>        → browser offers &quot;Install Tally&quot;</span></span>
<span class="line"><span>        → springboard icon: Tally&#39;s own, standalone display</span></span></code></pre></div><p><strong>Cold launch, signed in, offline:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tap icon → start_url /tally → SW offline-shells serves cached document</span></span>
<span class="line"><span>         → client hydrates from sdk.offline → cached data renders</span></span>
<span class="line"><span>         → OfflineBanner shows &quot;No internet connection&quot;</span></span></code></pre></div><p><strong>Cold launch, no session:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tap icon → /tally → middleware rewrites to the login document (200, in scope)</span></span>
<span class="line"><span>         → user signs in → returns to /tally, still in scope</span></span></code></pre></div><p><strong>Plugin not installable:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/manifest/&lt;id&gt; for a non-installable/disabled plugin → 404</span></span></code></pre></div><h2 id="alternatives-considered" tabindex="-1">Alternatives considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to &quot;Alternatives considered&quot;">​</a></h2><ul><li><strong><code>/&lt;routePrefix&gt;/manifest.webmanifest</code>.</strong> Rejected — inside the session-gated namespace, so a logged-out browser gets redirected to <code>/login</code> instead of a manifest and never offers an install. Would require a new matcher exclusion per plugin prefix, when <code>/api/manifest/</code> is already exempt for exactly this reason.</li><li><strong>Deriving installability from <code>offline: true</code>.</strong> Rejected — independent concerns; Launcher is offline-capable and should not become separately installable.</li><li><strong>One manifest per plugin, always served.</strong> Rejected — installability implies the plugin renders sensibly standalone and has a real icon set; it needs to be a deliberate author decision, not a default.</li><li><strong>A second service worker scoped to the plugin.</strong> Rejected — unnecessary (manifest scope is not SW scope) and actively harmful: two SWs on one origin with overlapping caches, both eligible to handle <code>/tally/*</code> navigations.</li><li><strong>Prepending the instance name to the app name.</strong> Rejected — the user is installing Tally. The instance is the backend, not the brand of the app.</li><li><strong>Redirecting rather than rewriting for the unauthenticated case.</strong> Rejected for the reason already recorded at <code>runtime/middleware.ts:320</code>.</li></ul><h2 id="open-questions" tabindex="-1">Open questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to &quot;Open questions&quot;">​</a></h2><ol><li>Does the maskable icon get an automatic background plate from the instance&#39;s <code>background_color</code>? Recommended yes; needs a visual check on Android.</li><li>Should <code>installable</code> imply anything about <code>shell</code>? An installed app arguably wants <code>shellConfig.mobileHeader: false</code> by default, but overriding a plugin&#39;s declared chrome from a different field is surprising. Leaning toward documenting the pairing and changing nothing.</li><li>Do PWA shortcuts (<code>shortcuts[]</code>, as the instance manifest uses for Launcher and Account) make sense per plugin, and if so where does a plugin declare them?</li><li>Where post-login return-to-plugin state lives so it survives the auth round-trip without a query parameter that would perturb <code>start_url</code> matching.</li></ol><h2 id="adoption-path" tabindex="-1">Adoption path <a class="header-anchor" href="#adoption-path" aria-label="Permalink to &quot;Adoption path&quot;">​</a></h2><ol><li><strong>Epic task 2.25</strong> — <code>installable</code> manifest field, <code>/api/manifest/[pluginId]</code> route, per-plugin <code>generateMetadata</code> including the Apple tags, the unauthenticated login rewrite, docs. <code>@sovereignfs/manifest</code> minor bump.</li><li><strong>Epic task 2.26</strong> — plugin PWA icon generation, validation that <code>installable: true</code> has a usable icon set, Docker asset-path wiring.</li><li>First adopters: two plugins, per research 0005&#39;s de-risking recommendation — one platform plugin and one real app (Tally) — before any of this is generalized further or RFC 0082 begins.</li></ol><h2 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Version</th><th>Date</th><th>Change</th></tr></thead><tbody><tr><td>0.1</td><td>July 2026</td><td>Initial draft</td></tr></tbody></table>`,55)])])}const g=a(n,[["render",o]]);export{u as __pageData,g as default};
